mapper.sql:
FROM case_payment_review pr JOIN service_record sr ON sr.id = pr.case_id LEFT JOIN service_policy sp ON sp.id = sr.policy_id WHERE sr.status = 'COMPLETED' AND pr.decision = 'APPROVED' AND pr.payout_amount > 0 AND pr.payment_confirmed_at IS NOT NULL
AND LOCATE(LOWER(#{query.name}), LOWER(COALESCE(NULLIF(TRIM(sr.reporter_name), ''), sr.name))) > 0
AND LOCATE(LOWER(#{query.policyNo}), LOWER(sp.policy_no)) > 0 AND pr.payment_confirmed_at >= #{query.fromTime} AND pr.payment_confirmed_at < #{query.untilTime}
